## Submitted testbench
```systemverilog
module tb;
  // -------------------------------------------------
  // Parameters and signal declarations
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;                 // 125 MHz clock
  logic               clk;
  logic               rst;
  logic [15:0]        prescale;
  logic [7:0]         s_axis_tdata;
  logic               s_axis_tvalid;
  logic               s_axis_tready;
  logic [7:0]         m_axis_tdata;
  logic               m_axis_tvalid;
  logic               m_axis_tready;
  logic               rxd;
  logic               txd;
  logic               tx_busy;
  logic               rx_busy;
  logic               rx_overrun_error;
  logic               rx_frame_error;

  // AXI‑Stream ports are tied off
  assign s_axis_tready = 1'b1;
  assign m_axis_tready = 1'b1;

  // -------------------------------------------------
  // DUT instantiation
  // -------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .rxd               (rxd),
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale)
  );

  // -------------------------------------------------
  // Clock generation
  // -------------------------------------------------
  initial clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  // Helper tasks
  // -------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b0; wait_clks(2);
    rst = 1'b1; wait_clks(2);
    rst = 1'b0; wait_clks(2);
  endtask

  // Send a serial frame on rxd.
  // data_byte : byte to be transmitted (LSB first)
  // stop_low  : 1'b1 -> stop bit forced low (induces frame_error)
  //             1'b0 -> normal stop bit (high)
  task automatic send_frame(input byte unsigned data_byte, input logic stop_low);
    integer i;
    int bit_clks;
    bit_clks = prescale * 8;

    // Start bit
    rxd = 1'b0;
    wait_clks(bit_clks);

    // Data bits (LSB first)
    for (i = 0; i < 8; i = i + 1) begin
      rxd = data_byte[i];
      wait_clks(bit_clks);
    end

    // Stop bit
    if (stop_low) rxd = 1'b0;
    else          rxd = 1'b1;
    wait_clks(bit_clks);

    // Return to idle (high)
    rxd = 1'b1;
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // Initialise all control signals
    rst          = 1'b0;
    prescale     = 16'd5;          // default prescale value
    s_axis_tdata = 8'd0;
    s_axis_tvalid= 1'b0;
    rxd          = 1'b1;           // idle state

    // Reset the design
    do_reset();

    // Small stabilisation delay
    wait_clks(100);

    // -------------------------------------------------
    // 1) Induce a frame_error by sending a frame with a low stop bit
    // -------------------------------------------------
    send_frame(8'h3C, 1'b1);       // stop_low = 1'b1 → frame_error pulse

    // Allow the receiver to finish processing and become idle
    wait_clks(200);

    // -------------------------------------------------
    // 2) Wait until the receiver is idle (busy low & rxd high) for
    //    at least 16 clocks – this satisfies the idle‑run condition.
    // -------------------------------------------------
    // We wait a generous number of cycles; the idle condition will
    // have been met well before this point.
    wait_clks(30);

    // -------------------------------------------------
    // 3) Send a normal frame that delivers 0xA5 with a valid stop bit.
    //    This frame will cause m_axis_tvalid to rise with data 8'hA5.
    // -------------------------------------------------
    send_frame(8'hA5, 1'b0);       // stop_low = 1'b0 → normal stop

    // Give the DUT a few cycles to present the word on the AXI stream.
    wait_clks(200);

    // -------------------------------------------------
    // 4) End simulation – the coverage point must have been hit.
    // -------------------------------------------------
    $finish;
  end
endmodule
